      }
    },
    {
      "id": "4",
      "type": "markdown-exporter",
      "param": {
        "target_type": "docx",
        "md_text": "{{#'3'.output#}}"
      }
    },
    {
      "id": "5",
      "type": "end",
      "param": {
        "outputs": [
          ["summary", ["output", "3"]],
          ["docx_file", ["files", "4"]]
        ]
      }
    }
  ],
