import re
import requests

def build_tree_structure(tree_data):
    """Convert GitHub tree data to text-based tree view"""

    # Group files by directory
    structure = {}
    for item in tree_data.get('tree', []):
        path_parts = item['path'].split('/')
        current = structure

        for part in path_parts[:-1]:
            if part not in current:
                current[part] = {}
            current = current[part]

        filename = path_parts[-1]
        if item['type'] == 'tree':
            if filename not in current:
                current[filename] = {}
        else:
            current[filename] = {'type': 'file', 'size': item.get('size', 0)}

    def format_tree(node, prefix=""):
        """Format the tree structure with proper indentation"""
        lines = []
        items = list(node.items())

        for i, (name, content) in enumerate(items):
            is_last = i == len(items) - 1

            if isinstance(content, dict) and 'type' in content:
                # It's a file
                lines.append(f"{prefix}{'└── ' if is_last else '├── '}{name}")
            else:
                # It's a directory
                lines.append(f"{prefix}{'└── ' if is_last else '├── '}{name}/")

                extension = "    " if is_last else "│   "
                lines.extend(format_tree(content, prefix + extension))

        return lines

    tree_lines = format_tree(structure)
    return '\n'.join(tree_lines)

def main(github_url: str):
    # Extract owner and repo from GitHub URL
    match = re.search(r'github\.com/([^/]+)/([^/]+)', github_url)
    if not match:
        return {"file_structure": "Error: Invalid GitHub URL format"}

    owner, repo = match.groups()
    repo = repo.replace('.git', '')

    # GitHub API endpoint for recursive tree
    api_url = f"https://api.github.com/repos/{owner}/{repo}/git/trees/HEAD?recursive=1"

    try:
        response = requests.get(api_url)
        response.raise_for_status()
        tree_data = response.json()

        tree_view = build_tree_structure(tree_data)
        full_structure = f"{owner}/{repo}/\n{tree_view}"

        return {"file_structure": full_structure}

    except requests.exceptions.RequestException as e:
        return {"file_structure": f"Error fetching repository structure: {str(e)}"}
    except Exception as e:
        return {"file_structure": f"Error processing repository: {str(e)}"}"
      }
