        ],
        "code": "import json, os\n\ndef main(cls: str, scr: str, file: dict):\n    data = json.loads(scr)\n    return {\n        \"result\": {\n            \"category\": cls,\n            \"file\": file,\n            \"score\": data[\"score\"],\n            \"reason\": data[\"reason\"]\n        }\n    }"
