        "outputs": [
          ["best_resumes", "array[file]"],
          ["reasons", "object"]
        ],
        "code": "def main(all: list):\n    buckets = {\n        \"ACCOUNTANT\": [],\n        \"ARTS\": [],\n        \"SALES\": [],\n        \"TEACHER\": []\n    }\n    for item in all:\n        buckets[item[\"category\"]].append(item)\n    best = {}\n    files = []\n    for cat, items in buckets.items():\n        if items:\n            top = max(items, key=lambda x: x[\"score\"])\n            best[cat] = {\"reason\": top[\"reason\"], \"file\": top[\"file\"]}\n            files.append(top[\"file\"])\n    return {\"best_resumes\": files, \"reasons\": best}"
      }
    },
